package io.figchain.client;

import com.example.trust.Destination;
import com.example.trust.Shipment;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Avro 1.12 refuses to instantiate classes outside its trusted packages. Records generated by
 * figchain-maven-plugin live in the user's packages, so the client must trust the classes it is
 * asked to decode, including nested records, without the user setting JVM properties.
 */
class AvroTrustTest {

    @Test
    void decodesGeneratedRecordsOutsideTrustedPackages() throws Exception {
        Shipment original = new Shipment("s-1", new Destination("Lisbon"));

        Shipment binary = AvroEncoding.deserializeBinary(AvroEncoding.serializeBinary(original), Shipment.class);
        assertEquals("Lisbon", binary.getTo().getCity().toString());

        Shipment withSchema = AvroEncoding.deserializeBinary(AvroEncoding.serializeBinary(original), Shipment.class, Shipment.SCHEMA$);
        assertInstanceOf(Destination.class, withSchema.getTo());

        Shipment container = AvroEncoding.deserializeWithSchema(AvroEncoding.serializeWithSchema(original), Shipment.class);
        assertEquals("Lisbon", container.getTo().getCity().toString());
    }

    @Test
    void classesTheAppDidNotAskForStayForbidden() throws Exception {
        AvroEncoding.trust(Shipment.class);
        // A schema could name any class; only requested records (and their nested types) are trusted
        assertThrows(SecurityException.class,
                () -> org.apache.avro.util.ClassSecurityValidator.validate(java.util.concurrent.ThreadPoolExecutor.class));
        assertThrows(SecurityException.class,
                () -> org.apache.avro.util.ClassSecurityValidator.validate(AvroTrustTest.class));
        assertDoesNotThrow(() -> org.apache.avro.util.ClassSecurityValidator.validate(Destination.class));
    }
}
